// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.valueoverlay;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Locale;

import org.junit.jupiter.api.Test;

class VectorPageBulkCopyTest {
	@Test
	void numericAndAlphabetEverySubrangeMatchesRead() {
		check(true);
	}

	@Test
	void alphabetAndRawByteEverySubrangeMatchesRead() {
		check(false);
	}

	private static void check(boolean digits) {
		PhysicalRecord[] records = new PhysicalRecord[16];
		for (int i = 0; i < records.length; i++) {
			byte[] bytes = String.format(Locale.ROOT, "fixed:%018d/%04x/Az+/%02d:end", i * 123456789L, i * 31, i)
					.getBytes(StandardCharsets.UTF_8);
			bytes[bytes.length - 1] = (byte) (128 + i); // independent non-alphabet byte field
			records[i] = new PhysicalRecord(bytes, false, bytes.length);
		}
		byte[] page = VectorPageCodec.encode(records, records.length, digits);
		assertNotNull(page);
		try (var allocator = new NativeSlabAllocator(1 << 20)) {
			allocator.copy(new byte[97]);
			long handle = allocator.copy(page);
			for (int slot = 0; slot < records.length; slot++) {
				byte[] expected = VectorPageCodec.read(allocator, handle, slot).bytes();
				assertArrayEquals(records[slot].bytes(), expected);
				var access = VectorPageCodec.openRecord(allocator, handle, slot);
				for (int from = 0; from <= expected.length; from++) {
					for (int count = 0; count <= expected.length - from; count++) {
						byte[] target = new byte[count + 8];
						Arrays.fill(target, (byte) 0x5a);
						byte[] wanted = target.clone();
						System.arraycopy(expected, from, wanted, 3, count);
						access.copy(from, target, 3, count);
						assertArrayEquals(wanted, target, "slot=" + slot + " from=" + from + " count=" + count);
					}
				}
				assertThrows(IndexOutOfBoundsException.class, () -> access.copy(-1, new byte[3], 0, 1));
				assertThrows(IndexOutOfBoundsException.class, () -> access.copy(0, new byte[3], -1, 1));
				assertThrows(IndexOutOfBoundsException.class, () -> access.copy(0, new byte[3], 3, 1));
				assertThrows(IndexOutOfBoundsException.class, () -> access.copy(expected.length, new byte[3], 0, 1));
				assertThrows(IndexOutOfBoundsException.class, () -> access.copy(0, new byte[3], 0, -1));
			}
		}
	}
}
